import { useMutation, useQuery, useQueryClient } from '@tanstack/react-query';
import type { AnomalyEvaluation } from '@domain/anomaly-engine.ts';
import { supabase, invokeFunction } from '@/lib/supabase/client';
import type { BusRow, EmployeeRow, RouteRow, TripRow } from '@/lib/supabase/database.types';
import { queryKeys } from '@/app/query-client';
import { useAuth } from '@/features/auth/session';
import { trackEvent } from '@/providers/analytics';

/**
 * Bus readings ("trips" in the database — the name predates this shape).
 *
 * One row per bus per day: a single OCR reading, not a start/end pair. The
 * write goes through `rpc_record_bus_reading`, which rejects a second
 * reading for the same bus on the same day and computes distance/efficiency
 * against that bus's *previous* reading. Anomaly evaluation happens
 * afterwards, in the `trip-finalise` Edge Function, which shares its engine
 * code with the browser (see `supabase/functions/_shared/domain`). The client
 * never decides whether a reading is anomalous.
 */

export interface TripWithRelations extends TripRow {
  bus?: Pick<
    BusRow,
    | 'id'
    | 'registration_number'
    | 'fleet_number'
    | 'dashboard_type'
    | 'tank_capacity_litres'
    | 'fuel_type'
  > | null;
  route?: Pick<
    RouteRow,
    'id' | 'name' | 'code' | 'expected_distance_km' | 'distance_tolerance_pct'
  > | null;
  driver?: Pick<EmployeeRow, 'id' | 'full_name' | 'employee_code'> | null;
}

const TRIP_SELECT = `
  *,
  bus:buses(id, registration_number, fleet_number, dashboard_type, tank_capacity_litres, fuel_type),
  route:routes(id, name, code, expected_distance_km, distance_tolerance_pct),
  driver:employees(id, full_name, employee_code)
`;

export interface TripFilters {
  depotId?: string | null;
  busId?: string | null;
  driverId?: string | null;
  routeId?: string | null;
  reviewStatus?: TripRow['review_status'] | 'ALL';
  from?: string;
  to?: string;
  limit?: number;
}

export function useTrips(filters: TripFilters = {}) {
  const { identity } = useAuth();

  return useQuery({
    queryKey: queryKeys.trips(filters),
    enabled: Boolean(identity),
    queryFn: async (): Promise<TripWithRelations[]> => {
      let query = supabase.from('trips').select(TRIP_SELECT);
      if (filters.depotId) query = query.eq('depot_id', filters.depotId);
      if (filters.busId) query = query.eq('bus_id', filters.busId);
      if (filters.driverId) query = query.eq('driver_id', filters.driverId);
      if (filters.routeId) query = query.eq('route_id', filters.routeId);
      if (filters.reviewStatus && filters.reviewStatus !== 'ALL') {
        query = query.eq('review_status', filters.reviewStatus);
      }
      if (filters.from) query = query.gte('reading_date', filters.from);
      if (filters.to) query = query.lte('reading_date', filters.to);

      const { data, error } = await query
        .order('captured_at', { ascending: false })
        .limit(filters.limit ?? 50);
      if (error) throw error;
      return (data ?? []) as unknown as TripWithRelations[];
    },
  });
}

export function useTrip(tripId: string | undefined) {
  return useQuery({
    queryKey: queryKeys.trip(tripId ?? ''),
    enabled: Boolean(tripId),
    queryFn: async (): Promise<TripWithRelations | null> => {
      const { data, error } = await supabase
        .from('trips')
        .select(TRIP_SELECT)
        .eq('id', tripId as string)
        .maybeSingle();
      if (error) throw error;
      return (data ?? null) as unknown as TripWithRelations | null;
    },
  });
}

/** Buses that haven't had a reading recorded yet today — what "Add bus details" chooses from. */
export function useBusesMissingTodayReading(depotId: string | null) {
  const { identity } = useAuth();
  return useQuery({
    queryKey: queryKeys.busesMissingTodayReading(depotId),
    enabled: Boolean(identity) && Boolean(depotId),
    staleTime: 15_000,
    queryFn: async (): Promise<Set<string>> => {
      const today = new Date().toISOString().slice(0, 10);
      let query = supabase.from('trips').select('bus_id').eq('reading_date', today);
      if (depotId) query = query.eq('depot_id', depotId);
      const { data, error } = await query;
      if (error) throw error;
      return new Set((data ?? []).map((row) => row.bus_id));
    },
  });
}

export interface RecordBusReadingInput {
  busId: string;
  routeId: string;
  driverId: string | null;
  odometerKm: number;
  rangeKm?: number | null;
  fuelPercent?: number | null;
  refuelLitres?: number | null;
  captureId?: string | null;
  shiftSlotId?: string | null;
}

export interface RecordBusReadingResult {
  trip: TripRow;
  /** Server-side evaluation. Absent if the finalise call could not be reached. */
  evaluation: AnomalyEvaluation | null;
}

export function useRecordBusReading() {
  const queryClient = useQueryClient();

  return useMutation({
    mutationKey: ['trip.recordReading'],
    mutationFn: async (input: RecordBusReadingInput): Promise<RecordBusReadingResult> => {
      const { data, error } = await supabase.rpc('rpc_record_bus_reading', {
        p_bus_id: input.busId,
        p_route_id: input.routeId,
        p_driver_id: input.driverId,
        p_odometer: input.odometerKm,
        p_range: input.rangeKm ?? null,
        p_fuel_percent: input.fuelPercent ?? null,
        p_refuel_litres: input.refuelLitres ?? null,
        p_capture_id: input.captureId ?? null,
        p_shift_slot_id: input.shiftSlotId ?? null,
      });
      if (error) throw error;
      const trip = data as unknown as TripRow;

      // The reading is already saved. Anomaly evaluation is a second, separate
      // step so that a transient failure in the analysis never costs the
      // driver the reading they just walked out to the bus to take.
      let evaluation: AnomalyEvaluation | null = null;
      try {
        const response = await invokeFunction<{ evaluation: AnomalyEvaluation }>('trip-finalise', {
          tripId: trip.id,
        });
        evaluation = response.evaluation;
      } catch {
        evaluation = null;
      }

      trackEvent('bus_reading_recorded', {
        has_capture: Boolean(input.captureId),
        anomaly_count: evaluation?.findings.length ?? 0,
      });

      return { trip, evaluation };
    },
    onSuccess: () => {
      void queryClient.invalidateQueries({ queryKey: ['trips'] });
      void queryClient.invalidateQueries({ queryKey: ['buses'] });
      void queryClient.invalidateQueries({ queryKey: ['anomalies'] });
      void queryClient.invalidateQueries({ queryKey: ['dashboard'] });
    },
  });
}

/** Dashboard captures and their per-field readings, for a bus reading. */
export function useTripCaptures(tripId: string | undefined) {
  return useQuery({
    queryKey: ['trips', 'captures', tripId],
    enabled: Boolean(tripId),
    queryFn: async () => {
      const { data, error } = await supabase
        .from('dashboard_captures')
        .select(
          'id, kind, storage_bucket, storage_path, captured_at, ocr_provider, ocr_engine_version, ocr_status, image_hash',
        )
        .eq('trip_id', tripId as string)
        .order('captured_at');
      if (error) throw error;

      const captureIds = (data ?? []).map((capture) => capture.id);
      if (captureIds.length === 0) return { captures: data ?? [], readings: [] };

      const readings = await supabase
        .from('dashboard_readings')
        .select('*')
        .in('capture_id', captureIds);
      if (readings.error) throw readings.error;

      return { captures: data ?? [], readings: readings.data ?? [] };
    },
  });
}
